{
  "contract": "TraderSpirits",
  "closure": {
    "site_function": "mintByUser",
    "site_call": ".call",
    "functions": [
      "mintByUser"
    ],
    "justification": "mintByUser is the only function that writes to the exposed storage variables and can be re-entered via the low-level call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "mintByUser"
    ],
    "nesting_bound": {
      "mintByUser": 1
    }
  },
  "phases": {
    "function": "mintByUser",
    "pre": {
      "name": "pre",
      "from_marker": "require(!isHalted && !isPaused, \"Contract is halted or paused\");",
      "to_marker": "require(msg.value >= mintPrice, \"Insufficient funds\");"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "require(msg.value >= mintPrice, \"Insufficient funds\");",
      "to_marker": "require(publicMinted <= publicMintLimit, \"Mint limit exceeded\");"
    },
    "post": {
      "name": "post",
      "from_marker": "require(publicMinted <= publicMintLimit, \"Mint limit exceeded\");",
      "to_marker": "emit Minted(msg.sender, quantity);"
    },
    "linearization_point": "require(publicMinted <= publicMintLimit, \"Mint limit exceeded\");"
  },
  "ghost_state": [],
  "exposure_invariant": {
    "formula": "publicMinted <= publicMintLimit",
    "stable_formula": "publicMinted <= publicMintLimit",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "publicMinted <= publicMintLimit",
    "rule": "The exposure invariant is the same as the stable invariant because the target property reads the same variables that are written before and after the call."
  }
}
